const COMMANDS: &[&str] = &["connect", "send", "close", "inspect_ticket", "probe_ticket"];

fn main() {
    // Autogenerates one `allow-<cmd>` / `deny-<cmd>` permission per
    // command under `permissions/autogenerated/`; the hand-written
    // `permissions/default.toml` bundles them as `peerline-iroh:default`.
    tauri_plugin::Builder::new(COMMANDS).build();
}
